import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { FiClipboard, FiArrowRight } from "react-icons/fi";
import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import FormField from "../../components/FormField";
import { studentApi } from "../../api/studentApi";
import { useLookupOptions } from "../../hooks/useLookupOptions";
import { fullName } from "../../utils/formatters";

export default function Registrations() {
  const navigate = useNavigate();
  const [studentId, setStudentId] = useState("");

  const { options: studentOptions, isLoading } = useLookupOptions(
    studentApi.getAll,
    (s) => ({ value: s.id, label: `${fullName(s)} — ${s.registration_number}` })
  );

  function handleView(e) {
    e.preventDefault();
    if (studentId) navigate(`/registrations/student/${studentId}`);
  }

  return (
    <DashboardLayout>
      <div className="flex items-center gap-2 mb-6">
        <div className="h-9 w-9 rounded-lg bg-navy-100 text-navy-700 flex items-center justify-center">
          <FiClipboard size={16} />
        </div>
        <h1 className="font-display text-xl text-navy-800">Student Courses</h1>
      </div>

      <Card className="p-6 max-w-lg">
        <p className="text-sm text-muted mb-4">
          Select a student to view their registered courses, or register a new
          enrollment from the sidebar.
        </p>
        <form onSubmit={handleView} className="flex flex-col sm:flex-row gap-3">
          <div className="flex-1">
            <FormField
              as="select"
              name="student_id"
              value={studentId}
              onChange={(e) => setStudentId(e.target.value)}
              options={studentOptions}
              placeholder={isLoading ? "Loading students..." : "Select a student"}
            />
          </div>
          <button
            type="submit"
            disabled={!studentId}
            className="flex items-center justify-center gap-2 bg-navy-700 text-white px-5 py-2.5 rounded-lg text-sm font-medium hover:bg-navy-800 transition disabled:opacity-50 shrink-0"
          >
            View Courses <FiArrowRight size={15} />
          </button>
        </form>
      </Card>
    </DashboardLayout>
  );
}
